From 2d7286d5713beda212f539c4bb251253f947811f Mon Sep 17 00:00:00 2001
From: Christopher Brannon 
Date: Sun, 2 May 2021 17:52:41 -0700
Subject: [PATCH] Fix out-of-bounds read when processing malformed SSML.

---
 CHANGELOG.md                       |  4 ++++
 src/libespeak-ng/readclause.c      | 23 +++++++++++++++--------
 tests/ssml/badly-escaped1.expected |  1 +
 tests/ssml/badly-escaped1.ssml     |  1 +
 tests/ssml/badly-escaped2.expected |  1 +
 tests/ssml/badly-escaped2.ssml     |  1 +
 6 files changed, 23 insertions(+), 8 deletions(-)
 create mode 100644 tests/ssml/badly-escaped1.expected
 create mode 100644 tests/ssml/badly-escaped1.ssml
 create mode 100644 tests/ssml/badly-escaped2.expected
 create mode 100644 tests/ssml/badly-escaped2.ssml

diff --git a/CHANGELOG.md b/CHANGELOG.md
index 865bd02be0..542b87e547 100644
--- a/CHANGELOG.md
+++ b/CHANGELOG.md
@@ -16,6 +16,10 @@ The espeak-ng project is a fork of the espeak project.
 *  New Language option: "lowercaseSentence" for ending a sentence if a period is followed by a lower case letter.
 *  Added voice variants

+bug fixes:
+*  Fix reading malformed SSML (Christopher Brannon)
+*  Fix memory allocation (Christopher Brannon)
+
 documentation:
 * Add documentation about voice and language options.
 * Add documentation about dictionary flags.
diff --git a/src/libespeak-ng/readclause.c b/src/libespeak-ng/readclause.c
index f3d2b4e8f3..25d51896d7 100644
--- a/src/libespeak-ng/readclause.c
+++ b/src/libespeak-ng/readclause.c
@@ -510,10 +510,13 @@ int ReadClause(Translator *tr, char *buf, short *charix, int *charix_top, int n_
 	tr->clause_lower_count = 0;
 	*tone_type = 0;

-	if (ungot_char2 != 0)
+	if (ungot_char2 != 0) {
 		c2 = ungot_char2;
-	else
+	} else if (Eof()) {
+		c2 = 0;
+	} else {
 		c2 = GetC();
+	}

 	while (!Eof() || (ungot_char != 0) || (ungot_char2 != 0) || (ungot_string_ix >= 0)) {
 		if (!iswalnum(c1)) {
@@ -542,14 +545,14 @@ int ReadClause(Translator *tr, char *buf, short *charix, int *charix_top, int n_

 		if ((ungot_string_ix == 0) && (ungot_char2 == 0))
 			c1 = ungot_string[ungot_string_ix++];
-		if (ungot_string_ix >= 0)
+		if (ungot_string_ix >= 0) {
 			c2 = ungot_string[ungot_string_ix++];
-		else {
+		} else if (Eof()) {
+			c2 = ' ';
+		} else {
 			c2 = GetC();
-
-			if (Eof())
-				c2 = ' ';
 		}
+
 		ungot_char2 = 0;

 		if ((option_ssml) && (phoneme_mode == 0)) {
@@ -561,7 +564,11 @@ int ReadClause(Translator *tr, char *buf, short *charix, int *charix_top, int n_
 					c1 = GetC();
 				}
 				xml_buf2[n_xml_buf] = 0;
-				c2 = GetC();
+				if (Eof()) {
+					c2 = '\0';
+				} else {
+					c2 = GetC();
+				}
 				sprintf(ungot_string, "%s%c%c", &xml_buf2[0], c1, c2);

 				int found = -1;
diff --git a/tests/ssml/badly-escaped1.expected b/tests/ssml/badly-escaped1.expected
new file mode 100644
index 0000000000..ec74f33b61
--- /dev/null
+++ b/tests/ssml/badly-escaped1.expected
@@ -0,0 +1 @@
+kəmpˈa͡ɪl ænd flˈæʃ lˈɪnɪɪd͡ʒ ˈændɹɔ͡ɪd ˌo͡ʊˈɛs
diff --git a/tests/ssml/badly-escaped1.ssml b/tests/ssml/badly-escaped1.ssml
new file mode 100644
index 0000000000..f5dcf5a9e9
--- /dev/null
+++ b/tests/ssml/badly-escaped1.ssml
@@ -0,0 +1 @@
+compile&flash Lineage Android OS
diff --git a/tests/ssml/badly-escaped2.expected b/tests/ssml/badly-escaped2.expected
new file mode 100644
index 0000000000..35cc624070
--- /dev/null
+++ b/tests/ssml/badly-escaped2.expected
@@ -0,0 +1 @@
+kəmpˈa͡ɪl ænd flˈæʃ
diff --git a/tests/ssml/badly-escaped2.ssml b/tests/ssml/badly-escaped2.ssml
new file mode 100644
index 0000000000..380562acaf
--- /dev/null
+++ b/tests/ssml/badly-escaped2.ssml
@@ -0,0 +1 @@
+compile&flash

